<section class="container section narrow"><h1>What Can I Make?</h1><form method="post" action="/what-can-i-make" class="card stack-form" data-what-can-i-make-form><?= \App\Util\Csrf::field() ?><label>Ingredients you have<input type="text" name="ingredients" value="<?= e(implode(', ', $ingredients ?? [])) ?>" placeholder="eggs, flour, butter" data-ingredient-chip-input></label><label>Match threshold: <strong><?= e((string) ((int) round(($threshold ?? 0.8) * 100))) ?>%</strong><input type="range" name="threshold" min="0.1" max="1" step="0.05" value="<?= e((string) ($threshold ?? 0.8)) ?>"></label><button class="button" type="submit">Find recipes</button></form><?php if (!empty($results)): ?><div class="section-header"><h2>Matches</h2></div><div class="recipe-grid"><?php foreach ($results as $match): $recipe = $match['recipe']; ?><div><?php include TEMPLATES_PATH . '/partials/recipe-card.php'; ?><p class="muted"><?= e((string) ((int) round($match['match_ratio'] * 100))) ?>% ingredient match</p></div><?php endforeach; ?></div><?php endif; ?></section>
